import { readFileSync } from "fs";

const [first, second] = readFileSync(0, "utf8").trim().split("\n");
const [, k] = first.split(" ").map(Number);
const a = second.split(" ").map(Number);

// これまでに現れた累積和ごとの個数
const seen = new Map<number, number>([[0, 1]]);
let prefix = 0;
let count = 0;
for (const x of a) {
  prefix += x;
  // prefix - (以前の累積和) = K となる以前の累積和の個数を足す
  count += seen.get(prefix - k) ?? 0;
  seen.set(prefix, (seen.get(prefix) ?? 0) + 1);
}
console.log(count);
